export const skillLabels={
 'present-time':['Настоящее время','Present time'],'past-time':['Прошедшее время','Past time'],'future-time':['Будущее время','Future time'],aspect:['Завершённость и длительность','Aspect'],conditionals:['Условия и последствия','Conditions and consequences'],modals:['Возможность и обязательства','Possibility and obligation'],determiners:['Артикли и определители','Articles and determiners'],quantity:['Количество','Quantity'],comparison:['Сравнение','Comparison'],'word-order':['Порядок слов','Word order'],reference:['Связь слов с контекстом','Reference'],passive:['Пассивные конструкции','Passive constructions'],'reported-speech':['Передача чужой речи','Reported speech'],'relative-clauses':['Уточняющие придаточные','Relative clauses'],linking:['Связь идей','Linking ideas'],collocation:['Сочетаемость слов','Collocation'],'word-formation':['Словообразование','Word formation'],register:['Уместность стиля','Register'],'pragmatic-meaning':['Смысл реплик в ситуации','Meaning in context'],stance:['Позиция и степень уверенности','Stance and certainty'],negation:['Отрицание','Negation'],prepositions:['Предлоги','Prepositions'],'lexical-meaning':['Значение слов','Word meaning'],gist:['Главная мысль','Main idea'],'explicit-detail':['Точная информация','Explicit detail'],detail:['Точная информация','Explicit detail'],inference:['Вывод из контекста','Inference'],'writer-attitude':['Позиция автора','Writer attitude'],attitude:['Позиция говорящего','Speaker attitude'],purpose:['Цель сообщения','Communicative purpose'],organisation:['Структура текста','Text organisation'],qualification:['Оговорки и ограничения','Qualifications and limits'],reason:['Причины и объяснения','Reasons and explanations'],'speaker-attitude':['Отношение говорящего','Speaker attitude'],'change-of-plan':['Изменение планов','Changes of plan'],agreement:['Согласие и разногласие','Agreement and disagreement'],sequence:['Последовательность','Sequence']
};
export const labelFor=(tag,language)=>skillLabels[tag]?.[language==='ru'?0:1]||tag.replaceAll('-',' ');
export function weekPlan(week,focus,language){
 const t=(ru,en)=>language==='ru'?ru:en,skill=focus?labelFor(focus.tag,language):t('смысл и точность ответов','meaning and accuracy');
 const plans=[
  {title:t('Найти причину трудности','Find the cause'),body:t(`Фокус: ${skill}. Выберите три ответа из своего разбора. До чтения объяснения запишите, почему выбрали вариант. Затем найдите точное основание в контексте и объясните, почему каждый другой вариант меняет смысл. Составьте список из трёх правил или наблюдений.`,`Focus: ${skill}. Choose three responses from your report. Before reading the explanation, write why you chose each option. Find the precise evidence in context and explain how every alternative changes the meaning. Keep three rules or observations.`)},
  {title:t('Практиковать с объяснением','Practise with explanations'),body:(focus?practiceFor(focus.domain,focus.tag,language):t('Подберите шесть новых примеров из незнакомого текста или записи. Сначала ответьте самостоятельно, затем проверьте себя по источнику.','Find six new examples in an unfamiliar text or recording. Answer independently before checking against the source.'))+' '+t('Запишите один собственный пример и один похожий пример-ловушку. На следующий день объясните разницу без заметок.','Write one example of your own and one tempting near-miss. Explain the difference the next day without notes.')},
  {title:t('Применить в своей речи','Use it in your own English'),body:t(`Фокус: ${skill}. Возьмите новую ситуацию из работы или учёбы. Напишите сообщение на 80–120 слов и запишите минутный устный ответ, применяя то, что практиковали. Попросите преподавателя отметить, где смысл ясен и где форма или формулировка мешает. Перепишите и перезапишите один фрагмент.`,`Focus: ${skill}. Take a new situation from work or study. Write an 80–120 word message and record a one-minute spoken response using what you practised. Ask a teacher where meaning is clear and where form or wording interferes. Rewrite and rerecord one part.`)},
  {title:t('Проверить перенос на новые задачи','Check transfer to new tasks'),body:t('Используйте новый текст, незнакомую запись и короткую самостоятельную письменную работу без подсказок. Сравните причины ошибок с первой неделей, а не только число верных ответов. Вместе с преподавателем выберите следующую цель; повтор старых ключей не подтверждает новый уровень.','Use a new text, unfamiliar recording and short independent writing task without hints. Compare the reasons for errors with week one, not just the number correct. Choose the next goal with a teacher; recalling old keys does not establish a new level.')}
 ];return plans[week-1];
}
export function practiceFor(domain,tag,language){
 const t=(ru,en)=>language==='ru'?ru:en;
 if(domain==='listening')return t('Прослушайте новый короткий разговор один раз. Запишите главную мысль, два факта и слова, которые изменили смысл. Прослушайте повторно и объясните расхождения. Затем повторите с незнакомой записью.','Listen to a new short conversation once. Note the main point, two facts and words that change the meaning. Replay and explain any differences. Repeat with an unfamiliar recording.');
 if(domain==='reading')return ['inference','writer-attitude','qualification'].includes(tag)?t('Возьмите новый текст. Для каждого вывода подчеркните две опорные фразы и отдельно запишите, чего автор не утверждает. Проверьте, не сильнее ли ваш вывод, чем доказательства.','Use a new text. Underline two supporting phrases for each inference and write down what the author does not claim. Check that your conclusion is no stronger than the evidence.'):t('Прочитайте новый текст и дайте каждому абзацу короткий заголовок. Найдите три точных ответа с указанием фразы-основания. Через день повторите с другим жанром текста.','Read a new text and give each paragraph a short heading. Find three precise answers and identify their supporting phrases. Repeat with a different text genre the next day.');
 if(['present-time','past-time','future-time','aspect','conditionals'].includes(tag))return t('Составьте шесть коротких ситуаций с разным временем или условием. Выберите форму, объясните её смысл и измените одно обстоятельство. Проверьте, как вместе с ним меняется форма.','Create six short situations with different times or conditions. Choose a form, explain its meaning, then change one circumstance. Check how the form changes with it.');
 if(['register','pragmatic-meaning','stance'].includes(tag))return t('Напишите одну просьбу, отказ и рекомендацию другу и незнакомому коллеге. Сравните степень прямоты и уверенности. Попросите преподавателя объяснить, как каждую реплику поймёт адресат.','Write a request, refusal and recommendation for a friend and an unfamiliar colleague. Compare directness and certainty. Ask a teacher how a recipient would interpret each response.');
 return t('Соберите шесть новых примеров на эту тему. Для каждого объясните, почему выбранное выражение подходит по смыслу, а близкий вариант меняет смысл или структуру. На следующий день составьте свои примеры без подсказки.','Collect six new examples of this feature. Explain why each expression fits and how a nearby alternative changes its meaning or structure. The next day, create your own examples without a model.');
}
export const writingTasks={
 foundation:{label:['Базовые задачи','Foundation tasks'],tasks:[{id:'foundation-message',prompt:'You cannot attend your English class tomorrow. Write a message to your teacher. Explain why, ask about the homework, and suggest when you can catch up.',guidance:['Ориентир: 40–70 слов.','Aim for 40–70 words.']},{id:'foundation-place',prompt:'Describe a place you often go to. Explain what you do there, what you like about it, and one thing you would change.',guidance:['Ориентир: 70–100 слов.','Aim for 70–100 words.']}]},
 independent:{label:['Самостоятельное общение','Independent communication'],tasks:[{id:'independent-email',prompt:'You booked a short training course, but the organiser has changed it to a time you cannot attend. Write an email explaining the problem, comparing two possible solutions, and requesting a specific next step.',guidance:['Ориентир: 120–170 слов.','Aim for 120–170 words.']},{id:'independent-opinion',prompt:'Your college or workplace can fund either a quiet study room or more social events. Recommend one option, explain the benefits and a possible disadvantage, and respond to a reasonable objection.',guidance:['Ориентир: 180–240 слов.','Aim for 180–240 words.']}]},
 advanced:{label:['Развёрнутая аргументация','Extended argument'],tasks:[{id:'advanced-proposal',prompt:'A community centre has limited space. Some members want more organised classes; others want open access for independent activities. Write a proposal that weighs both needs, recommends a workable compromise, and explains how its success could be evaluated.',guidance:['Ориентир: 220–280 слов.','Aim for 220–280 words.']},{id:'advanced-analysis',prompt:'A colleague claims that making a service easier to use always makes it fairer. Write a response that examines this claim, develops a counterexample, acknowledges the strongest part of the argument, and reaches a qualified conclusion.',guidance:['Ориентир: 250–320 слов.','Aim for 250–320 words.']}]}
};

